// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint256 seed, address player) public {
        vm.assume(seed > 0);
        vm.assume(player != address(0));
        vm.assume(uint160(player) > 10);

        // Fix the block environment from the fuzzed seed: the draw is
        // keccak256(block.timestamp, block.difficulty) % 2, so the fuzzer
        // effectively searches the whole outcome space.
        vm.warp(seed);
        vm.roll(seed);

        vm.deal(player, 1000 ether);
        vm.prank(player);
        try c.play{value: 10}() {
            // no-op
        } catch {
            // revert path: play cannot revert here, but stay safe
        }

        uint256 r = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;

        // General rule: when the drawn outcome is 0, C pays out the whole pot
        // (fee to bank, rest to the player) and resets pot to 0; otherwise the
        // pot holds exactly the single ticket, 10. This holds for C for every
        // input, but the mutant pays on outcome 1 instead, so for outcome-0
        // draws it leaves pot == 10.
        assertTrue(r == 0 ? c.pot() == 0 : c.pot() == 10);
    }
}
